class FEMenu;
class FEManager;
class IGOFrontEnd;
class game;
class kellyslater_controller;
class world_dynamics_system;

class FEMenu
{
public:
  virtual void HighlightDefault(void);
  virtual void OnUnactivate(FEMenu* m);
};

class FEMenuSystem
{
protected:
  bool button_down[19][2];
  int device_flags;
public:
  FEMenu** menus;
  FEManager* manager;
  int active;
  int size;
  int count;
  void* font;
  virtual ~FEMenuSystem();
  virtual void InitAll();
  virtual void Add(FEMenu* m);
  virtual void MakeActive(int index, int sub_menu=1);
  virtual void Update(float time_inc);
  virtual void UpdateButtonDown();
  virtual void Draw();
  virtual void Select(int menu_index, int entry_index) = 0;
  virtual void Exit();
  virtual void startDraw(int menu_num = -1, const bool pauseGame = true);
  virtual void endDraw(const bool unpause = true);
  virtual FEMenu * GetActiveMenu(void);
protected:
  virtual void cons(int s, FEManager* man, void* f);
  virtual void OnButtonPress(int button, int controller);
public:
  void SetDeviceFlags(int _df) { device_flags = _df; }
};

class IGOFrontEnd
{
public:
  enum RUNSTATE { RUNSTATE_NORMAL };
  void SetDisplay(bool display);
  RUNSTATE GetRunState();
  void ShowMenuBackground(bool show);
};

class FEManager
{
public:
  IGOFrontEnd* IGO;
};

class kellyslater_controller
{
public:
  int get_super_state() const;
};

class game
{
public:
  int get_active_player(void);
  void unpause();
  int get_game_mode(void);
  int get_beach_id(void);
};

class world_dynamics_system
{
public:
  kellyslater_controller* get_ks_controller(int hero_num);
};

class app
{
public:
  static app* inst();
  game* get_game();
};

extern game* g_game_ptr;
extern world_dynamics_system* g_world_ptr;
enum { BEACH_INDOOR = 1, GAME_MODE_CAREER = 0, SUPER_STATE_FLYBY = 4 };

class PauseMenuSystem : public FEMenuSystem
{
public:
  enum { PauseMenu, TimeAttackPauseMenu, TutorialPauseMenu, EndRunMenu,
         HeatMidMenu, HeatEndMenu, CompEndMenu, OptionsMenu, GoalsMenu,
         LostControllerMenu, SoundMenu, CameraMenu, TrickTypeMenu,
         PlaylistMenu, ReplayMenu, MapMenu, HighScoreMenu, PhotoMenu,
         TutorialMenu, SaveLoadMenu, SaveConfirmMenu, TipMenu,
         QuitConfirmMenu, NumMenus };
  bool draw;
  bool replay_mode;
  bool end_level;
  int pause_controller;
  int pause_player;
  void* map;
  void* player;
  int popupEvent;
  int navigationEvent;
  virtual void endDraw(const bool unpause = true);
private:
  int old_device_flags;
  bool controller_disconnected;
};

void PauseMenuSystem::endDraw(const bool unpause)
{
  int i;

  if (!draw)
    return;

  SetDeviceFlags( old_device_flags );
  pause_controller = -1;
  pause_player = -1;

  if (!replay_mode)
  {
    kellyslater_controller * ksctrl = g_world_ptr->get_ks_controller(g_game_ptr->get_active_player());

    if (unpause)
      app::inst()->get_game()->unpause();

    if (g_game_ptr->get_beach_id() == BEACH_INDOOR && g_game_ptr->get_game_mode() == GAME_MODE_CAREER)
      manager->IGO->SetDisplay(true);
    else if (ksctrl->get_super_state() != SUPER_STATE_FLYBY && manager->IGO->GetRunState() == IGOFrontEnd::RUNSTATE_NORMAL)
      manager->IGO->SetDisplay(manager->score_display);

    manager->IGO->ShowMenuBackground(false);
  }

  for (i = 0; i < NumMenus; i++)
    menus[i]->HighlightDefault();

  menus[active]->OnUnactivate(0);


  draw = false;
}
